#include <iostream>

using namespace std;

int main() {
    int n, a[50] = {0}, ans = 0;
    cin >> n;
    for(int i = 1; i <= n; i++) {
        int t = i, pos = 0;
        while(t) {
            a[pos++] = t % 2;
            t /= 2;
        }
        bool ok = true;
        for(int i = 0; i < pos; i++)
            if(a[i] != a[pos - i - 1]) {
                ok = false;
                break;
            }
        ans += ok;
    }
    cout << ans;
    return 0;
}

#include <iostream>
#include <cstring>

using namespace std;

int main() {
    string s1, s2, s3;
    cin >> s1 >> s2 >> s3;
    int d = s1[0] - s2[0];
    d = (d % 26 + 26) % 26;
    for(int i = 0; i < s3.length(); i++) {
        int ch = (s3[i] - 'A' + d) % 26;
        cout << (char)(ch + 'A');
    }
    return 0;
}
